def deploy(self, id_networkv4):
        """Deploy network in equipments and set column 'active = 1' in tables redeipv4

        :param id_networkv4: ID for NetworkIPv4

        :return: Equipments configuration output
        """
        net_ipv4 = NetworkIPv4.objects.get(pk=id_networkv4)
        for eqt in Equipamento.objects.filter(ambiente__rede__id__in=[net_ipv4.id]):
            try:
                cmd = 'ip -4 route add {0} dev {1}'.format(net_ipv4.networkv4, eqt.interface_name)
                output = self._execute_command(eqt, cmd)
                self._set_active(id_networkv4, eqt.id)
            except Exception, e:
                raise NetworkIPv4Error(str(e), e)

